import json
from cpmpy import *

def schur(n=13, c=3):
    model = Model()

    # M[i,j] is true if ball i is in box j
    M = boolvar(shape=(n, c), name="M")

    # each ball is in exactly one box
    for i in range(n):
        model += sum(M[i]) == 1

    # for each triple (x, y, z) with x + y = z, not all are in the same box
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            z = x + y
            if z <= n:
                for j in range(c):
                    model += M[x - 1, j] + M[y - 1, j] + M[z - 1, j] <= 2

    return model, (M,)

# Example usage
model, (M,) = schur(n, c)
if model.solve():
    balls = [next((j + 1 for j, x in enumerate(row) if x), None) for row in M.value()]
    solution = {"balls": balls}
    print(json.dumps(solution))
else:
    print("No solution found.")
# End of CPMPy script
```

