from cpmpy import *
import json
import itertools

# Define the operations
ops = ['+2', '/8', '-3', '*7']

# Generate all permutations of operations
perms = list(itertools.permutations(ops))

# Initialize variables
m = intvar(1, 100, name="m")  # my age
h = intvar(1, 100, name="h")  # husband's age

# Model
model = Model()

# Apply operations in different orders
for p1 in perms:
    for p2 in perms:
        if p1 == p2:
            continue
        # Apply operations to my age
        expr_m = m
        for op in p1:
            if op == '+2':
                expr_m += 2
            elif op == '/8':
                expr_m = expr_m / 8
            elif op == '-3':
                expr_m -= 3
            elif op == '*7':
                expr_m *= 7
        # Apply operations to husband's age
        expr_h = h
        for op in p2:
            if op == '+2':
                expr_h += 2
            elif op == '/8':
                expr_h = expr_h / 8
            elif op == '-3':
                expr_h -= 3
            elif op == '*7':
                expr_h *= 7
        # Check if the final expressions are equal to each other's ages
        model += (expr_m == h) & (expr_h == m)

# Solve the model
if model.solve():
    solution = {"m": m.value(), "h": h.value()}
    print(json.dumps(solution))
else:
    print("No solution found.")
